import{_ as o,o as a,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot","description":"","frontmatter":{"date":"2026-10-21T00:00:00.000Z","title":"刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot","summary":"在 X 上回复帖子时 @bot，帖子连同你的要求会直接变成你主 Bot 的任务。开通条件、5 句好用的写法，以及 @bot 不回你时逐条排查。","category":"使用技巧","tags":["X","连接器","故障排查"],"sources":[{"url":"https://docs.x.ai/grok-bot/tag-on-x","author":"Tag @bot on X","platform":"官方文档"},{"url":"https://x.com/AiBraders/status/2112133162495050227","author":"@AiBraders","platform":"X"}],"updates":[{"link":"/faq/faq","title":"常见问题：新增「能在 X 上直接把帖子交给 Bot 吗」"},{"link":"/resources/","title":"资源导航 · 值得关注的博主：新增 Grok Bot 官方账号 @bot"}],"wordCount":784,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot | WANGXXXL"}],["meta",{"property":"og:description","content":"在 X 上回复帖子时 @bot，帖子连同你的要求会直接变成你主 Bot 的任务。开通条件、5 句好用的写法，以及 @bot 不回你时逐条排查。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-21-tag-bot-on-x"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-21-tag-bot-on-x-34a4954c34.png"}],["meta",{"property":"og:image:alt","content":"刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot | WANGXXXL"}],["meta",{"name":"twitter:description","content":"在 X 上回复帖子时 @bot，帖子连同你的要求会直接变成你主 Bot 的任务。开通条件、5 句好用的写法，以及 @bot 不回你时逐条排查。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-21-tag-bot-on-x-34a4954c34.png"}],["meta",{"name":"twitter:image:alt","content":"刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-21-tag-bot-on-x"}]]},"headers":[],"relativePath":"daily/2026-10-21-tag-bot-on-x.md","filePath":"daily/2026-10-21-tag-bot-on-x.md","lastUpdated":1792514041000}'),r={name:"daily/2026-10-21-tag-bot-on-x.md"};function s(i,t,l,p,d,c){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="刷-x-看到好帖-回复一句「-bot」就把它交给你的-bot" tabindex="-1">刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot <a class="header-anchor" href="#刷-x-看到好帖-回复一句「-bot」就把它交给你的-bot" aria-label="Permalink to &quot;刷 X 看到好帖，回复一句「@bot」就把它交给你的 Bot&quot;">​</a></h1><p>刷到一条值得研究的帖子：一份工具清单、一篇长教程、一个新发布的项目。以前要复制链接、打开 Grok Bot、粘贴、再交代要做什么。现在<strong>直接在那条帖子下面回复 <code>@bot</code> 加一句要求</strong>就行。</p><p>按<a href="https://docs.x.ai/grok-bot/tag-on-x" target="_blank" rel="noopener noreferrer">官方文档</a>：@bot 会在 X 上回一句短话，确认已经交给你的 Grok Bot；<strong>你的主 Bot 随即在云电脑上开工，过程和结果都留在 Grok Bot App 的对话里</strong>，不会公开发在 X 上。</p><h2 id="bot-能拿到什么" tabindex="-1">Bot 能拿到什么 <a class="header-anchor" href="#bot-能拿到什么" aria-label="Permalink to &quot;Bot 能拿到什么&quot;">​</a></h2><p>你的这条回复、你回复的那条帖子，以及两者引用的帖子（包括里面的图片）。所以<strong>直接回复在原帖下面</strong>效果最好，不用另外贴链接。</p><h2 id="开通前要满足的条件" tabindex="-1">开通前要满足的条件 <a class="header-anchor" href="#开通前要满足的条件" aria-label="Permalink to &quot;开通前要满足的条件&quot;">​</a></h2><ul><li>在 grok.com 的 <strong>设置 → Account</strong> 里，把你的 X 账号连到 Grok 账号（点 𝕏 Account 旁边的 Connect）。</li><li>同一个 Grok 账号开通了 Grok Bot，并且<strong>至少有一个你自己的 Bot</strong>。别人分享给你的 Bot 接不了这类任务。</li><li>第一次成功时，X 会提醒你：这类请求会自动开工，用的是你的 Grok Bot 用量。</li><li>X 插件（搜帖子、读时间线）不是必需的，没装也能转交。</li></ul><h2 id="_5-句好用的写法" tabindex="-1">5 句好用的写法 <a class="header-anchor" href="#_5-句好用的写法" aria-label="Permalink to &quot;5 句好用的写法&quot;">​</a></h2><p>回复时 <code>@bot</code> 后面直接写要求，越具体越好：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@bot 把这条帖子里提到的工具逐个查一下：官网、开源许可证、最近一次更新时间，做成表格放到我的资料库，别关注任何人</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@bot 这个串讲的方法帮我用到我的周报例程上，先给我改动方案，别直接改</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@bot 读完这篇长文，提炼 5 条我能照着做的步骤，每条附原文对应段落</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@bot 这个 GitHub 项目帮我评估一下：能不能装在你的电脑上用、要哪些权限、有没有风险。先别安装</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@bot 这条帖子说的省用量的办法，对照检查我现在的例程，列出可以合并或降低频率的，等我确认再改</span></span></code></pre></div><p>最后一句有真实用例：<a href="https://x.com/AiBraders/status/2112133162495050227" target="_blank" rel="noopener noreferrer">@AiBraders</a> 在一条讲省用量的帖子下 @bot，Bot 读完后检查了他所有的 Bot，删减了 4 个例程。我们建议加上&quot;等我确认再改&quot;，改例程这种事先看方案更稳。</p><h2 id="bot-不回你-逐条查" tabindex="-1">@bot 不回你？逐条查 <a class="header-anchor" href="#bot-不回你-逐条查" aria-label="Permalink to &quot;@bot 不回你？逐条查&quot;">​</a></h2><p>官方说明：<strong>@bot 没回复，就说明你的 Bot 没收到</strong>。常见原因：</p><table tabindex="0"><thead><tr><th>情况</th><th>怎么办</th></tr></thead><tbody><tr><td>你的 X 账号登记的国家或地区暂不支持（目前不支持澳大利亚、英国、欧盟、冰岛、列支敦士登、挪威；X 只登记了大区或没有登记国家的也不行）</td><td>只看 X 记录的账号所在地，<strong>换 VPN、换位置都没用</strong></td></tr><tr><td>你回复的串里已经有人 @bot，但你自己没写 @bot</td><td>自己再写一次 <code>@bot</code></td></tr><tr><td>同一条里还 @ 了 @grok</td><td>去掉 @grok 再发</td></tr><tr><td>你的帖子、被回复的帖子或被引用的帖子里有视频或 GIF</td><td>换一条不带视频的帖子，或把链接发到 App 里</td></tr><tr><td>内容没通过平台审核</td><td>换个说法</td></tr><tr><td>Grok Bot 没连到 Grok 账号，或本周用量用完</td><td>去 App 里确认</td></tr></tbody></table><p>@bot 回的是 &quot;Sign up for Grok Bot&quot; 说明 X 账号没连 Grok 账号；回 &quot;Grok Bot isn&#39;t set up yet&quot; 说明连上了，但你还没有自己的 Bot，先去 App 里建一个。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li><strong>@bot 的回复是公开的</strong>，但只有一句确认，你的要求本身也是公开回复。别在回复里写私人信息，具体要求可以简短写，细节到 App 里补。</li><li>转交的任务和你在 App 里交代的一样，发消息、下单、删除之类照样先出审批卡片。</li></ul>',21)])])}const h=o(r,[["render",s]]);export{g as __pageData,h as default};
